const modules=[['password','🔐','Password Lab','Assess password strength and generate strong passwords.'],['phishing','🎣','Phishing Lab','Investigate URL warning signs and phishing messages.'],['network','🌐','Network Defender','Stop a simulated intrusion by isolating network devices.'],['crypto','🗝️','Encryption Lab','Encrypt and decrypt local files in your browser.'],['quiz','🎯','Challenge Arena','Test your knowledge in a cybersecurity quiz.'],['dashboard','📊','My Dashboard','View your learning activity on this device.']];
