const app=document.querySelector('#app');
app.innerHTML=`<header class="topbar"><a class="brand" href="#home">⬡ <span>CYBER<span class="accent">VERSE</span></span></a><nav><a href="#modules">Explore Labs</a><a href="#dashboard">Dashboard</a><a href="#about">About</a></nav><button id="menuBtn" class="menu" aria-label="Toggle menu">☰</button></header><main><section class="hero" id="home"><div class="hero-copy"><div class="eyebrow">✦ INTERACTIVE CYBERSECURITY EXPERIENCE</div><h1>ENTER THE <span>CYBERVERSE</span></h1><p>Explore the world of cybersecurity through immersive 3D visuals, practical browser tools and safe hands-on simulations.</p><div class="actions"><a class="primary" href="#modules">Explore Labs ↗</a><a class="secondary" href="#about">How it works</a></div><div class="hero-stats"><div><strong>06</strong><small>Interactive labs</small></div><div><strong>100%</strong><small>Browser based</small></div><div><strong>0</strong><small>Accounts needed</small></div></div></div><div class="scene-wrap"><canvas id="scene" aria-label="Animated 3D laptop"></canvas><div class="float-label fl-one">🛡️ SECURE YOUR WORLD</div><div class="float-label fl-two">⚡ THREAT DETECTED</div><div class="float-label fl-three">🔒 ENCRYPTED</div></div><div class="scroll-note">SCROLL TO EXPLORE ↓</div></section><section id="modules" class="section"><div class="section-head"><span class="eyebrow">THE LABS</span><h2>Learn. Experiment. <em>Defend.</em></h2><p>Pick a module to launch an interactive security exercise.</p></div><div class="module-grid">${modules.map(([id,emoji,name,desc],i)=>`<button class="module-card" data-open="${id}"><span class="module-icon">${emoji}</span><span class="module-index">0${i+1}</span><h3>${name}</h3><p>${desc}</p><span class="open-link">LAUNCH LAB ↗</span></button>`).join('')}</div></section><section id="workspace" class="section workspace"><div class="section-head"><span class="eyebrow">YOUR WORKSPACE</span><h2 id="labTitle">Select a lab above</h2><p id="labDesc">Your interactive tools will appear here.</p></div><div id="labContent" class="lab-content"><div class="empty">Choose any lab card to get started.</div></div></section><section id="about" class="section about"><span class="eyebrow">ABOUT CYBERVERSE</span><h2>Built to make security <em>tangible.</em></h2><p>CyberVerse is a frontend-only educational playground. All exercises run in your browser. Simulated incidents are not connected to real networks, and URL checks are heuristic indicators—not malware scanning or a safety guarantee.</p><div class="portfolio-grid"><div class="panel"><h3>Our mission</h3><p>Learn defensive security by experimenting with safe, local simulations. CyberVerse is an independent educational project, not a live scanning service.</p></div><div class="panel"><h3>Technology stack</h3><p>HTML5 · CSS3 · JavaScript · Three.js · GSAP · Vite · Web Crypto API · localStorage</p></div><div class="panel"><h3>Project source</h3><p>Publish the code to GitHub, then add your repository link in the configuration at the top of <code>src/main.js</code>.</p><a class="secondary" id="githubLink" href="#about">GitHub repository not linked yet</a></div></div></section></main><footer>⬡ CYBERVERSE <span>Learn responsibly. Built with JavaScript, Three.js and GSAP.</span></footer>`;
const $=s=>document.querySelector(s);if(GITHUB_REPOSITORY_URL.startsWith('https://github.com/')){$('#githubLink').href=GITHUB_REPOSITORY_URL;$('#githubLink').textContent='View source on GitHub ↗';$('#githubLink').target='_blank';$('#githubLink').rel='noopener noreferrer'}
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const getStats=()=>{try{return JSON.parse(localStorage.getItem('cv_stats'))||{checks:0,quizzes:0,simulations:0,encryptions:0}}catch{return {checks:0,quizzes:0,simulations:0,encryptions:0}}};
const inc=k=>{const x=getStats();x[k]=(x[k]||0)+1;localStorage.setItem('cv_stats',JSON.stringify(x))};
$('#menuBtn').onclick=()=>$('.topbar nav').classList.toggle('visible');
$('.topbar nav').addEventListener('click',()=>$('.topbar nav').classList.remove('visible'));
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openLab(b.dataset.open));
const titles=Object.fromEntries(modules.map(x=>[x[0],[x[2],x[3]]]));
function openLab(id){$('#labTitle').textContent=titles[id][0];$('#labDesc').textContent=titles[id][1];const target=$('#labContent');target.innerHTML='';({password,phishing,network,crypto:cryptoLab,quiz,dashboard})[id](target);$('#workspace').scrollIntoView({behavior:'smooth'});gsap.fromTo(target,{opacity:0,y:18},{opacity:1,y:0,duration:.5})}
function password(el){el.innerHTML=`<div class="panel"><label for="pw">Enter a test password (avoid real passwords)</label><div class="input-row"><input id="pw" type="password" autocomplete="off" placeholder="Type a sample password..."/><button id="togglePw" class="secondary">Show</button></div><div class="meter"><div id="meterFill"></div></div><p id="pwResult" class="feedback">Start typing to evaluate strength.</p><div class="divider"></div><h3>Secure password generator</h3><div class="input-row"><input id="generated" readonly aria-label="Generated password"/><button class="primary" id="generate">Generate</button><button class="secondary" id="copyPw">Copy</button></div><p class="hint">Generated locally with cryptographically secure randomness. Nothing is saved.</p></div>`;const pw=$('#pw');$('#togglePw').onclick=()=>{pw.type=pw.type==='password'?'text':'password';$('#togglePw').textContent=pw.type==='password'?'Show':'Hide'};pw.oninput=()=>{const s=pw.value;let score=0;if(s.length>=12)score++;if(s.length>=16)score++;if(/[A-Z]/.test(s)&&/[a-z]/.test(s))score++;if(/\d/.test(s)&&/[^\w]/.test(s))score++;if(/password|123456|qwerty|admin|abcdef/i.test(s))score=Math.min(score,1);const labels=['Very weak','Weak','Fair','Good','Strong'];$('#meterFill').style.width=s?`${(score+1)*20}%`:'0%';$('#meterFill').style.background=['#ff5578','#ff9963','#ffcb66','#5ac8a3','#49e2d0'][score];$('#pwResult').textContent=s?`${labels[score]} · ${s.length} characters. ${s.length<12?'Try 12–16+ characters.':'Prefer unique passwords for every account.'}`:'Start typing to evaluate strength.'};$('#generate').onclick=()=>{const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*?';const arr=new Uint32Array(20);crypto.getRandomValues(arr);$('#generated').value=Array.from(arr,n=>chars[n%chars.length]).join('')};$('#copyPw').onclick=async()=>{if(!$('#generated').value)return;try{await navigator.clipboard.writeText($('#generated').value);$('#copyPw').textContent='Copied!'}catch{$('#generated').select();$('#copyPw').textContent='Select & copy'}}}
function phishing(el){el.innerHTML=`<div class="panel"><h3>URL risk indicators</h3><p class="hint">This analyzer does not visit the URL or confirm whether a site is malicious.</p><label for="urlInput">Enter a URL</label><div class="input-row"><input id="urlInput" type="text" placeholder="https://example.com/login"/><button class="primary" id="checkUrl">Analyze</button></div><div id="urlResult" class="feedback"></div><div class="divider"></div><h3>Spot the phishing message</h3><div class="example-mail"><strong>Subject: URGENT — Your account will be closed!</strong><p>Click http://account-verify.example/login immediately to avoid suspension. Send us your password to restore access.</p></div><button id="reveal" class="secondary">Reveal warning signs</button><p id="revealText" class="feedback"></p></div>`;$('#checkUrl').onclick=()=>{let raw=$('#urlInput').value.trim();let u;try{u=new URL(raw);if(!['http:','https:'].includes(u.protocol))throw Error()}catch{$('#urlResult').textContent='Enter a complete http:// or https:// URL.';return}const flags=[];if(u.protocol==='http:')flags.push('Connection does not use HTTPS');if(/^(\d{1,3}\.){3}\d{1,3}$/.test(u.hostname))flags.push('Uses an IP address instead of a domain');if(u.hostname.includes('xn--'))flags.push('Punycode domain: verify spelling carefully');if(u.hostname.split('.').length>4)flags.push('Unusually many subdomains');if(u.username||u.password)flags.push('URL contains embedded credentials');if(u.hostname.length>45)flags.push('Very long hostname');if(/(?:login|verify|secure|account).*(?:update|urgent|confirm)/i.test(u.pathname))flags.push('Urgent account-verification wording in path');inc('checks');$('#urlResult').innerHTML=`<strong>${flags.length?'Review recommended':'No selected warning patterns detected'}</strong><p>${flags.length?flags.map(f=>'• '+escapeHtml(f)).join('<br>'):'This does not mean the website is safe. Check the exact domain and use trusted bookmarks.'}</p>`};$('#reveal').onclick=()=>$('#revealText').textContent='Warning signs: urgency, threats of account closure, an unfamiliar link, and a request to disclose a password.'}
function network(el){el.innerHTML=`<div class="panel"><h3>Network defense scenario</h3><p class="hint">Educational simulation only: no real network traffic is generated.</p><div class="network"><div class="node good" id="router">🌐<small>Gateway</small></div><div class="wire"></div><div class="node good" id="server">🖥️<small>Server</small></div><div class="wire"></div><div class="node good" id="pc">💻<small>Workstation</small></div></div><p class="feedback" id="netStatus">Network secure. Start a simulated incident.</p><div class="input-row"><button class="primary" id="attack">Start scenario</button><button class="secondary" id="isolate">Isolate workstation</button><button class="secondary" id="resetNet">Reset</button></div></div>`;let attacked=false,isolated=false;$('#attack').onclick=()=>{attacked=true;isolated=false;$('#pc').className='node danger';$('#netStatus').textContent='Simulated suspicious activity detected at workstation. Isolate it to contain the incident.'};$('#isolate').onclick=()=>{if(!attacked){$('#netStatus').textContent='Start the scenario first.';return}if(!isolated){isolated=true;$('#pc').className='node isolated';$('#netStatus').textContent='Workstation isolated. Simulated threat contained!';inc('simulations')}};$('#resetNet').onclick=()=>{attacked=false;isolated=false;$('#pc').className='node good';$('#netStatus').textContent='Network secure. Start a simulated incident.'}}
async function deriveKey(pass,salt){const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
function downloadBytes(bytes,name){const blob=new Blob([bytes]);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function cryptoLab(el){el.innerHTML=`<div class="panel"><h3>Local AES-GCM file encryption</h3><p class="hint">Files never leave your device. Keep your password: lost passwords cannot be recovered. Test with non-sensitive files first.</p><label for="fileInput">Choose a file (maximum 10 MB)</label><input id="fileInput" type="file"/><label for="filePass">Encryption password (at least 12 characters)</label><input id="filePass" type="password" autocomplete="new-password" placeholder="Use a strong, unique password"/><div class="input-row"><button id="encrypt" class="primary">Encrypt & download</button><button id="decrypt" class="secondary">Decrypt .cvenc file</button></div><p id="cryptoStatus" class="feedback">Ready. Encrypted files have a .cvenc extension.</p></div>`;async function process(mode){const f=$('#fileInput').files[0],pass=$('#filePass').value,output=$('#cryptoStatus');if(!f||f.size>10*1024*1024||pass.length<12){output.textContent='Choose a file under 10 MB and enter a password of at least 12 characters.';return}try{const bytes=new Uint8Array(await f.arrayBuffer());if(mode==='encrypt'){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));const key=await deriveKey(pass,salt);const encrypted=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,bytes));const result=new Uint8Array(4+16+12+encrypted.length);result.set([67,86,48,49]);result.set(salt,4);result.set(iv,20);result.set(encrypted,32);downloadBytes(result,f.name+'.cvenc');inc('encryptions');output.textContent='Encrypted file downloaded.'}else{if(bytes.length<49||String.fromCharCode(...bytes.slice(0,4))!=='CV01')throw Error('Not a CyberVerse encrypted file');const key=await deriveKey(pass,bytes.slice(4,20));const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes.slice(20,32)},key,bytes.slice(32));downloadBytes(new Uint8Array(plain),f.name.replace(/\.cvenc$/,'')||'decrypted-file');output.textContent='Decrypted file downloaded.'}}catch(e){output.textContent='Operation failed. Check the password and file format.'}}$('#encrypt').onclick=()=>process('encrypt');$('#decrypt').onclick=()=>process('decrypt')}
const questions=[{"topic":"Fundamentals","q":"What does the CIA triad stand for?","options":["Confidentiality, Integrity, Availability","Control, Identity, Access","Cloud, Internet, Authentication"],"correct":0,"why":"The CIA triad describes three foundational security goals."},{"topic":"Fundamentals","q":"Which principle gives users only needed access?","options":["Least privilege","Open access","Shared administrator accounts"],"correct":0,"why":"Least privilege reduces the impact of mistakes and compromise."},{"topic":"Fundamentals","q":"What is a vulnerability?","options":["A weakness that could be exploited","A confirmed attacker","A backup copy"],"correct":0,"why":"A vulnerability is a weakness; exploitation is not guaranteed."},{"topic":"Fundamentals","q":"What is a threat?","options":["A potential cause of harm","A security patch","A password policy"],"correct":0,"why":"Threats may exploit vulnerabilities to cause harm."},{"topic":"Fundamentals","q":"Which action helps protect against data loss?","options":["Maintain tested backups","Disable logging","Reuse passwords"],"correct":0,"why":"Backups support recovery from incidents and failures."},{"topic":"Fundamentals","q":"What does patch management address?","options":["Known software weaknesses","Only screen brightness","Physical cable length"],"correct":0,"why":"Updates often fix vulnerabilities and bugs."},{"topic":"Fundamentals","q":"Which is an example of defense in depth?","options":["MFA plus access controls plus monitoring","One shared password","Disabling alerts"],"correct":0,"why":"Multiple layers reduce reliance on a single control."},{"topic":"Fundamentals","q":"What does risk generally combine?","options":["Likelihood and impact","Only file size","Only internet speed"],"correct":0,"why":"Risk assessment considers how likely and damaging an event may be."},{"topic":"Fundamentals","q":"Which is a security incident?","options":["Unauthorized access to an account","Scheduled backup completion","Successful routine login"],"correct":0,"why":"An incident can compromise security objectives."},{"topic":"Fundamentals","q":"What should you do first when you notice a suspected breach at work?","options":["Follow the incident reporting process","Delete all evidence","Post credentials online"],"correct":0,"why":"Prompt reporting preserves evidence and enables response."},{"topic":"Passwords","q":"What is multi-factor authentication?","options":["Using independent authentication factors","Using two passwords","Changing a username"],"correct":0,"why":"MFA combines different types of evidence."},{"topic":"Passwords","q":"Which password is generally stronger?","options":["A long unique random password","password123","CompanyName2026"],"correct":0,"why":"Length and unpredictability improve resistance to guessing."},{"topic":"Passwords","q":"Why use a password manager?","options":["To create and store unique passwords","To share passwords publicly","To turn off MFA"],"correct":0,"why":"Password managers help avoid reuse."},{"topic":"Passwords","q":"What is credential stuffing?","options":["Trying leaked credentials on other services","Encrypting a backup","Updating a browser"],"correct":0,"why":"Reused passwords make credential stuffing effective."},{"topic":"Passwords","q":"What is a passphrase?","options":["A sequence of words used as a password","A network cable","A firewall rule"],"correct":0,"why":"Long unique passphrases can be memorable and strong."},{"topic":"Passwords","q":"Which is safer for account recovery?","options":["Secure recovery methods and backup codes","Publicly posting backup codes","Using the same password everywhere"],"correct":0,"why":"Recovery codes must be protected like credentials."},{"topic":"Passwords","q":"Why are SMS codes sometimes less secure than authenticator apps?","options":["SIM-swap and interception risks","SMS always uses no encryption","Apps require no phone"],"correct":0,"why":"SMS-based MFA can face phone-number takeover risks."},{"topic":"Passwords","q":"What is password spraying?","options":["Trying a few common passwords across many accounts","Hashing one password","Rotating encryption keys"],"correct":0,"why":"Spraying spreads attempts across accounts."},{"topic":"Passwords","q":"When should a compromised password be changed?","options":["As soon as compromise is suspected","Only once every ten years","Never if it is long"],"correct":0,"why":"Suspected exposed credentials should be replaced promptly."},{"topic":"Passwords","q":"What is the best use of generated passwords?","options":["A different password for each account","One password for every site","Posting them in chat"],"correct":0,"why":"Uniqueness limits damage from a single leak."},{"topic":"Phishing","q":"What is phishing?","options":["Deceptive messages intended to steal information or induce action","A backup method","A type of file compression"],"correct":0,"why":"Phishing uses impersonation and persuasion."},{"topic":"Phishing","q":"Which is a common warning sign?","options":["Urgent request to verify credentials through a link","Expected monthly newsletter","Known bookmark"],"correct":0,"why":"Unexpected urgency and credential requests deserve scrutiny."},{"topic":"Phishing","q":"What is spear phishing?","options":["Targeted phishing tailored to a person or group","A firewall update","A browser feature"],"correct":0,"why":"Spear phishing uses specific details to seem credible."},{"topic":"Phishing","q":"How should you verify a suspicious bank message?","options":["Contact the bank using a known official channel","Reply with your password","Use the message link"],"correct":0,"why":"Independent verification avoids attacker-controlled links."},{"topic":"Phishing","q":"Does HTTPS prove a website is legitimate?","options":["No, it only indicates an encrypted connection","Yes, always","Only on phones"],"correct":0,"why":"Attackers can also use HTTPS."},{"topic":"Phishing","q":"What is a lookalike domain?","options":["A domain designed to resemble a trusted one","A backup DNS server","A local IP address"],"correct":0,"why":"Attackers may use spelling changes or similar characters."},{"topic":"Phishing","q":"What is smishing?","options":["Phishing via SMS or text messages","A password hashing algorithm","Network scanning"],"correct":0,"why":"Smishing targets users through text messages."},{"topic":"Phishing","q":"What is vishing?","options":["Voice-based phishing","Virus encryption","VPN tunneling"],"correct":0,"why":"Vishing uses phone calls or voice channels."},{"topic":"Phishing","q":"What should you do with an unexpected attachment?","options":["Verify the sender and context before opening","Enable macros immediately","Forward to everyone"],"correct":0,"why":"Unexpected files may carry malicious content."},{"topic":"Phishing","q":"Why is the visible link text not always trustworthy?","options":["Its destination may be different","Links cannot be spoofed","Browsers always block fraud"],"correct":0,"why":"Inspect actual destinations without opening suspicious links."},{"topic":"Network","q":"What is a firewall used for?","options":["Filtering network traffic according to rules","Storing passwords","Creating 3D models"],"correct":0,"why":"Firewalls enforce traffic policy."},{"topic":"Network","q":"What does DNS primarily do?","options":["Resolve domain names to network addresses","Encrypt all files","Scan for malware"],"correct":0,"why":"DNS supports name resolution."},{"topic":"Network","q":"What is a VPN?","options":["An encrypted tunnel between endpoints or networks","An antivirus signature","A password manager"],"correct":0,"why":"VPNs protect traffic in certain network contexts."},{"topic":"Network","q":"What is network segmentation?","options":["Separating networks into controlled zones","Disabling all routers","Making every host public"],"correct":0,"why":"Segmentation limits unnecessary connectivity."},{"topic":"Network","q":"What is an IP address?","options":["An address identifying a network interface","A file checksum","A password type"],"correct":0,"why":"IP addresses enable network routing and communication."},{"topic":"Network","q":"What is the role of an IDS?","options":["Detect suspicious activity and alert","Always block every packet","Replace all backups"],"correct":0,"why":"Intrusion detection systems monitor for suspicious patterns."},{"topic":"Network","q":"Which port is typically associated with HTTPS?","options":["443","25","53"],"correct":0,"why":"HTTPS commonly uses TCP port 443."},{"topic":"Network","q":"What is a DDoS attack?","options":["Overwhelming a service with distributed traffic","Encrypting a local file","Changing a password"],"correct":0,"why":"Distributed denial-of-service attacks target availability."},{"topic":"Network","q":"What does zero trust emphasize?","options":["Verify explicitly and limit access","Trust all internal devices","Disable authentication"],"correct":0,"why":"Zero trust avoids assuming trust based on network location."},{"topic":"Network","q":"Why should unused network services be disabled?","options":["They increase the attack surface","They improve encryption","They make passwords longer"],"correct":0,"why":"Reducing exposed services reduces potential entry points."},{"topic":"Web Security","q":"What is XSS?","options":["Injection of script into a web context","A secure hashing method","A network protocol"],"correct":0,"why":"Cross-site scripting can run attacker-controlled script in a victim context."},{"topic":"Web Security","q":"What helps prevent SQL injection?","options":["Parameterized queries","Concatenating raw user input","Disabling logs"],"correct":0,"why":"Parameterization separates data from SQL instructions."},{"topic":"Web Security","q":"What is CSRF?","options":["Tricking a browser into making an unwanted authenticated request","A file encryption algorithm","A DNS lookup"],"correct":0,"why":"CSRF abuses existing browser authentication state."},{"topic":"Web Security","q":"What is broken access control?","options":["Users can access actions or data they should not","A weak Wi-Fi signal","A slow website"],"correct":0,"why":"Authorization must be enforced for every protected resource."},{"topic":"Web Security","q":"What is input validation?","options":["Checking that input meets expected constraints","Trusting every string","Disabling TLS"],"correct":0,"why":"Validation helps reject unexpected input but is not a complete defense."},{"topic":"Web Security","q":"What is the purpose of Content Security Policy?","options":["Restrict allowed content sources and script execution","Store passwords","Replace HTTPS"],"correct":0,"why":"CSP can reduce the impact of some injection attacks."},{"topic":"Web Security","q":"What is an insecure direct object reference?","options":["Accessing another object by manipulating an identifier without authorization","A browser bookmark","A type of encryption"],"correct":0,"why":"Object-level authorization checks are required."},{"topic":"Web Security","q":"Why should API secrets not be placed in frontend JavaScript?","options":["Visitors can inspect downloaded code","JavaScript is always encrypted","Browsers hide all variables"],"correct":0,"why":"Client-delivered code cannot safely hold shared secrets."},{"topic":"Web Security","q":"What does HTTPS protect?","options":["Data in transit between endpoints","All server-side vulnerabilities","Every user password forever"],"correct":0,"why":"TLS protects communication, not application logic."},{"topic":"Web Security","q":"What does output encoding help prevent?","options":["Interpreting untrusted data as executable markup","Slow internet","Forgotten passwords"],"correct":0,"why":"Context-appropriate encoding reduces injection risk."},{"topic":"Cryptography","q":"What does encryption primarily provide?","options":["Confidentiality","Guaranteed availability","Automatic backups"],"correct":0,"why":"Encryption conceals plaintext from unauthorized readers."},{"topic":"Cryptography","q":"What does a hash function produce?","options":["A fixed-size digest for a given algorithm","A reversible password","A network route"],"correct":0,"why":"Cryptographic hashes map input to a digest."},{"topic":"Cryptography","q":"Is SHA-256 hashing the same as encryption?","options":["No, hashes are not designed to be decrypted","Yes, identical","Only for text files"],"correct":0,"why":"Hashing and encryption serve different purposes."},{"topic":"Cryptography","q":"What does AES-GCM provide?","options":["Authenticated encryption","Only image compression","DNS resolution"],"correct":0,"why":"AES-GCM protects confidentiality and detects tampering."},{"topic":"Cryptography","q":"Why must AES-GCM nonces be unique per key?","options":["Reuse can seriously undermine security","To make files smaller","To improve font rendering"],"correct":0,"why":"Nonce reuse with the same key is dangerous."},{"topic":"Cryptography","q":"What is a digital signature used for?","options":["Verify authenticity and integrity","Hide all metadata","Compress files"],"correct":0,"why":"Signatures help verify the signer and detect changes."},{"topic":"Cryptography","q":"What is a salt in password hashing?","options":["A unique random value combined with each password","A shared master password","A network firewall"],"correct":0,"why":"Salts help prevent identical hashes and precomputed attacks."},{"topic":"Cryptography","q":"Why use a password-based key derivation function?","options":["Make password guessing more costly","Disable authentication","Convert images to text"],"correct":0,"why":"KDFs such as PBKDF2 deliberately add computational work."},{"topic":"Cryptography","q":"What is public-key cryptography?","options":["Using mathematically related public and private keys","Sharing one password with everyone","A browser extension"],"correct":0,"why":"Asymmetric systems use distinct keys for different roles."},{"topic":"Cryptography","q":"What happens if an encryption key is lost?","options":["Protected data may become unrecoverable","Encryption automatically reverses","The file becomes public"],"correct":0,"why":"Key management and backups are essential."}];

const extraQuestions=[{"topic": "Fundamentals", "q": "A coworker reports an unexpected MFA prompt. What should they do?", "options": ["Deny it and report the attempt", "Approve to stop notifications", "Share the code with IT"], "correct": 0, "why": "Unexpected MFA prompts can indicate an account takeover attempt.", "difficulty": "Beginner"}, {"topic": "Fundamentals", "q": "A laptop holding customer records is lost. What should be checked first?", "options": ["Device encryption and incident reporting", "Screen resolution", "Wallpaper settings"], "correct": 0, "why": "Encryption and incident response affect exposure.", "difficulty": "Intermediate"}, {"topic": "Fundamentals", "q": "A team needs to share a document securely. What is best?", "options": ["Restricted access with expiry where appropriate", "Public link without restrictions", "Emailing credentials"], "correct": 0, "why": "Access restrictions reduce unintended disclosure.", "difficulty": "Advanced"}, {"topic": "Fundamentals", "q": "A system stores sensitive logs. What is important?", "options": ["Access control and retention limits", "Public indexing", "Disable all audit trails"], "correct": 0, "why": "Logs can contain sensitive information.", "difficulty": "Beginner"}, {"topic": "Fundamentals", "q": "What is a good first step in threat modeling?", "options": ["Identify assets and trust boundaries", "Choose a brand color", "Disable authentication"], "correct": 0, "why": "Understand what needs protection and where trust changes.", "difficulty": "Intermediate"}, {"topic": "Fundamentals", "q": "An alert seems false. What should an analyst do?", "options": ["Validate evidence before closing", "Delete logs", "Ignore future alerts"], "correct": 0, "why": "Evidence-based triage prevents missed incidents.", "difficulty": "Advanced"}, {"topic": "Passwords", "q": "An account uses a long password but no MFA. Best improvement?", "options": ["Enable MFA", "Shorten password", "Share recovery codes"], "correct": 0, "why": "MFA adds a distinct protective factor.", "difficulty": "Beginner"}, {"topic": "Passwords", "q": "A site announces a password database breach. What should users do?", "options": ["Change affected and reused passwords", "Ignore it", "Post passwords for checking"], "correct": 0, "why": "Credential reuse creates cascading risk.", "difficulty": "Intermediate"}, {"topic": "Passwords", "q": "Which secret should never be stored in public source code?", "options": ["API token", "CSS color", "Page title"], "correct": 0, "why": "Public repositories are not secret storage.", "difficulty": "Advanced"}, {"topic": "Passwords", "q": "What is a safer recovery code practice?", "options": ["Store codes in a protected location", "Screenshot publicly", "Reuse them as passwords"], "correct": 0, "why": "Recovery codes can bypass normal sign-in.", "difficulty": "Beginner"}, {"topic": "Passwords", "q": "What makes a password generator reliable?", "options": ["Cryptographically secure randomness", "Current timestamp only", "A fixed dictionary sequence"], "correct": 0, "why": "Secure random sources improve unpredictability.", "difficulty": "Intermediate"}, {"topic": "Passwords", "q": "A user receives an MFA code without logging in. What now?", "options": ["Do not share it and review account security", "Send it to the caller", "Approve the login"], "correct": 0, "why": "Unsolicited codes can signal an attack.", "difficulty": "Advanced"}, {"topic": "Phishing", "q": "A message asks you to scan a QR code to reset payroll access. Best step?", "options": ["Verify through the official portal", "Scan immediately", "Forward to all colleagues"], "correct": 0, "why": "QR codes can conceal destinations.", "difficulty": "Beginner"}, {"topic": "Phishing", "q": "A sender display name matches your manager but the address differs. What matters?", "options": ["Verify the real sender and request", "Trust the display name", "Reply with credentials"], "correct": 0, "why": "Display names are easy to impersonate.", "difficulty": "Intermediate"}, {"topic": "Phishing", "q": "An unexpected invoice attachment asks to enable macros. What now?", "options": ["Do not enable macros; verify the invoice", "Enable macros", "Upload it to social media"], "correct": 0, "why": "Macros can execute unwanted code.", "difficulty": "Advanced"}, {"topic": "Phishing", "q": "A login page uses HTTPS but an unfamiliar domain. Is it trustworthy?", "options": ["Not necessarily", "Always", "Only if it loads quickly"], "correct": 0, "why": "TLS does not establish organizational legitimacy.", "difficulty": "Beginner"}, {"topic": "Phishing", "q": "A support caller asks for your one-time code. What should you do?", "options": ["Refuse and verify independently", "Share the code", "Turn off MFA"], "correct": 0, "why": "Legitimate support should not need your one-time code.", "difficulty": "Intermediate"}, {"topic": "Phishing", "q": "A short link hides its destination. What is safer?", "options": ["Use a known official site instead", "Click to inspect", "Assume short links are safe"], "correct": 0, "why": "Unknown redirects can conceal malicious destinations.", "difficulty": "Advanced"}, {"topic": "Network", "q": "A workstation is making unusual outbound connections. First action?", "options": ["Follow triage and containment procedures", "Disable every firewall", "Publish internal IPs"], "correct": 0, "why": "Incident response balances evidence and containment.", "difficulty": "Beginner"}, {"topic": "Network", "q": "Why separate guest Wi-Fi from internal systems?", "options": ["Limit lateral access", "Increase password reuse", "Disable monitoring"], "correct": 0, "why": "Segmentation reduces exposure.", "difficulty": "Intermediate"}, {"topic": "Network", "q": "What should a default-deny firewall policy do?", "options": ["Allow only explicitly required traffic", "Allow all incoming traffic", "Block only DNS"], "correct": 0, "why": "Least-privilege network rules reduce attack surface.", "difficulty": "Advanced"}, {"topic": "Network", "q": "What can a sudden spike in failed logins indicate?", "options": ["Possible password spraying", "Successful backup", "Normal patching always"], "correct": 0, "why": "Patterns of authentication failures deserve investigation.", "difficulty": "Beginner"}, {"topic": "Network", "q": "Which data helps investigate suspicious traffic?", "options": ["Firewall and network flow logs", "Wallpaper history", "Keyboard color"], "correct": 0, "why": "Network telemetry provides evidence.", "difficulty": "Intermediate"}, {"topic": "Network", "q": "What is a safe response to a suspected infected host?", "options": ["Isolate according to incident procedure", "Delete all logs", "Share admin credentials"], "correct": 0, "why": "Containment helps prevent spread while preserving evidence.", "difficulty": "Advanced"}, {"topic": "Web Security", "q": "A page inserts untrusted text into innerHTML. Main concern?", "options": ["Cross-site scripting", "Disk fragmentation", "DNS propagation"], "correct": 0, "why": "Untrusted HTML can execute scripts.", "difficulty": "Beginner"}, {"topic": "Web Security", "q": "A user changes an order ID and sees another customer order. What failed?", "options": ["Object-level authorization", "Font loading", "Image compression"], "correct": 0, "why": "Each object access needs authorization.", "difficulty": "Intermediate"}, {"topic": "Web Security", "q": "An API accepts arbitrary client-provided roles. What should change?", "options": ["Enforce roles on the server", "Hide the role input", "Use darker buttons"], "correct": 0, "why": "Authorization cannot trust client claims.", "difficulty": "Advanced"}, {"topic": "Web Security", "q": "Which cookie flag helps protect against JavaScript reading cookies?", "options": ["HttpOnly", "Autoplay", "Preload"], "correct": 0, "why": "HttpOnly blocks JavaScript access to the cookie.", "difficulty": "Beginner"}, {"topic": "Web Security", "q": "Why use prepared statements?", "options": ["Separate SQL code from values", "Speed up animations", "Prevent every phishing attack"], "correct": 0, "why": "Parameterization reduces SQL injection.", "difficulty": "Intermediate"}, {"topic": "Web Security", "q": "A web form reflects raw HTML from user input. What helps?", "options": ["Context-appropriate output encoding", "Disable backups", "Expose API keys"], "correct": 0, "why": "Output encoding prevents data becoming executable markup.", "difficulty": "Advanced"}, {"topic": "Cryptography", "q": "You need to verify a downloaded file was unchanged. Use what?", "options": ["A trusted cryptographic checksum", "File extension alone", "Screen brightness"], "correct": 0, "why": "Digest comparison detects changes when the expected digest is trusted.", "difficulty": "Beginner"}, {"topic": "Cryptography", "q": "Why use a random salt for password hashing?", "options": ["Reduce identical hashes and precomputation", "Make passwords visible", "Compress data"], "correct": 0, "why": "Salts must be unique per stored password.", "difficulty": "Intermediate"}, {"topic": "Cryptography", "q": "What does authenticated encryption detect?", "options": ["Ciphertext tampering", "All phishing", "Power loss"], "correct": 0, "why": "AEAD modes protect integrity as well as confidentiality.", "difficulty": "Advanced"}, {"topic": "Cryptography", "q": "Why should a private key be protected?", "options": ["It can authorize sensitive operations", "It is a CSS setting", "It is always public"], "correct": 0, "why": "Private keys must remain confidential.", "difficulty": "Beginner"}, {"topic": "Cryptography", "q": "Why is nonce reuse dangerous with AES-GCM?", "options": ["It can break confidentiality and integrity", "It improves security", "It only changes file names"], "correct": 0, "why": "AES-GCM requires unique nonces per key.", "difficulty": "Intermediate"}, {"topic": "Cryptography", "q": "Which practice supports secure encryption?", "options": ["Documented algorithms and sound key management", "Inventing custom ciphers", "Hardcoding keys in browser code"], "correct": 0, "why": "Use vetted primitives and protect keys.", "difficulty": "Advanced"}, {"topic": "Fundamentals", "q": "Which security control helps restore data after ransomware?", "options": ["Offline, tested backups", "Public password lists", "Disable alerts"], "correct": 0, "why": "Recovery requires usable backups.", "difficulty": "Beginner"}, {"topic": "Fundamentals", "q": "What is an attack surface?", "options": ["All possible entry points", "Only one server", "The desktop wallpaper"], "correct": 0, "why": "Reducing exposed entry points limits opportunities.", "difficulty": "Intermediate"}, {"topic": "Passwords", "q": "What is a passkey designed to reduce?", "options": ["Password phishing", "Screen glare", "Disk usage"], "correct": 0, "why": "Passkeys use origin-bound public-key authentication.", "difficulty": "Advanced"}, {"topic": "Passwords", "q": "Why should login attempts be rate limited?", "options": ["Reduce automated guessing", "Improve graphics", "Remove MFA"], "correct": 0, "why": "Rate limits constrain brute-force attempts.", "difficulty": "Beginner"}, {"topic": "Phishing", "q": "What is business email compromise?", "options": ["Fraudulent use of business communication", "Routine newsletter", "Encrypted backups"], "correct": 0, "why": "BEC often targets payments and sensitive requests.", "difficulty": "Intermediate"}, {"topic": "Phishing", "q": "What is the safest way to report a suspicious email?", "options": ["Use the organization reporting channel", "Reply with details", "Forward externally"], "correct": 0, "why": "Official reporting enables investigation.", "difficulty": "Advanced"}, {"topic": "Network", "q": "What does TLS mainly protect?", "options": ["Data in transit", "Data on disconnected disks", "All endpoint malware"], "correct": 0, "why": "TLS protects network communications.", "difficulty": "Beginner"}, {"topic": "Network", "q": "Why monitor DNS requests?", "options": ["They may reveal suspicious destinations", "They reveal password contents", "They replace backups"], "correct": 0, "why": "DNS telemetry can aid detection.", "difficulty": "Intermediate"}, {"topic": "Web Security", "q": "What is the purpose of CSRF tokens?", "options": ["Bind sensitive requests to legitimate sessions", "Encrypt all database records", "Improve 3D performance"], "correct": 0, "why": "Tokens help prevent unwanted authenticated requests.", "difficulty": "Advanced"}, {"topic": "Web Security", "q": "Why validate uploads on the server?", "options": ["Clients can bypass frontend checks", "It changes font sizes", "It eliminates every risk"], "correct": 0, "why": "Client validation alone is not a security boundary.", "difficulty": "Beginner"}, {"topic": "Cryptography", "q": "What is key rotation?", "options": ["Replacing keys under a managed policy", "Renaming folders", "Changing screen colors"], "correct": 0, "why": "Rotation limits exposure when managed carefully.", "difficulty": "Intermediate"}, {"topic": "Cryptography", "q": "What does a digital signature verify?", "options": ["Authenticity and integrity", "File secrecy by itself", "Network speed"], "correct": 0, "why": "Signatures verify signed data and signer keys.", "difficulty": "Advanced"}];
questions.forEach((q,i)=>q.difficulty=["Beginner","Intermediate","Advanced"][i%3]);
questions.push(...extraQuestions);

function quiz(el){
 let pool=[],idx=0,score=0,answered=false,topic='All topics',level='practice',difficulty='All levels',startTime=0;
 const shuffle=items=>{const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
 function setup(){el.innerHTML=`<div class="panel"><span class="eyebrow">CYBERVERSE CHALLENGE ARENA 2.0</span><h3>Choose your challenge</h3><p class="hint">108 curated questions across six topics. Practice with 10 random questions or take a 20-question assessment. Answers are explained after selection.</p><label for="quizTopic">Topic</label><select id="quizTopic" class="cv-select"><option>All topics</option>${[...new Set(questions.map(q=>q.topic))].map(t=>`<option>${escapeHtml(t)}</option>`).join('')}</select><label for="quizDifficulty">Difficulty</label><select id="quizDifficulty" class="cv-select"><option>All levels</option><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select><label for="quizMode">Mode</label><select id="quizMode" class="cv-select"><option value="practice">Practice · 10 questions</option><option value="assessment">Assessment · up to 20 questions</option><option value="full">Full topic · all available questions</option></select><div class="input-row"><button class="primary" id="startQuiz">Start challenge →</button></div><p class="hint">Your highest percentage score is saved locally. Questions are not a professional certification.</p></div>`;
 $('#startQuiz').onclick=()=>{topic=$('#quizTopic').value;level=$('#quizMode').value;difficulty=$('#quizDifficulty').value;startTime=Date.now();const available=questions.filter(q=>(topic==='All topics'||q.topic===topic)&&(difficulty==='All levels'||q.difficulty===difficulty));const limit=level==='practice'?10:level==='assessment'?20:available.length;pool=shuffle(available).slice(0,limit).map(q=>{const options=shuffle(q.options.map((text,i)=>({text,original:i})));return {...q,options:options.map(x=>x.text),correct:options.findIndex(x=>x.original===q.correct)}});idx=0;score=0;render()};
 }
 function render(){if(idx>=pool.length){inc('quizzes');const pct=Math.round(score/pool.length*100);const old=Number(localStorage.getItem('cv_best_quiz')||0);const history=readHistory();history.unshift({topic,difficulty,mode:level,score,pct,total:pool.length,date:new Date().toISOString(),seconds:Math.round((Date.now()-startTime)/1000)});localStorage.setItem('cv_history',JSON.stringify(history.slice(0,100)));if(pct>old)localStorage.setItem('cv_best_quiz',String(pct));el.innerHTML=`<div class="panel"><span class="eyebrow">CHALLENGE COMPLETED</span><h3>${escapeHtml(topic)}</h3><p class="big-score">${score}/${pool.length}</p><p>${pct}% correct · ${pct>=80?'Excellent work!':pct>=60?'Good progress — review the explanations.':'Keep practicing and build your fundamentals.'}</p><p class="hint">Best recorded score: ${Math.max(pct,old)}%</p><button class="primary" id="again">Choose another challenge</button></div>`;$('#again').onclick=setup;return}
 answered=false;const q=pool[idx];el.innerHTML=`<div class="panel"><span class="eyebrow">${escapeHtml(q.topic.toUpperCase())} · QUESTION ${idx+1} OF ${pool.length}</span><div class="quiz-progress"><span style="width:${idx/pool.length*100}%"></span></div><h3>${escapeHtml(q.q)}</h3><div class="answers">${q.options.map((o,i)=>`<button class="answer" data-answer="${i}">${escapeHtml(o)}</button>`).join('')}</div><p id="explanation" class="feedback" aria-live="polite">Choose one answer to reveal the explanation.</p><button class="primary" id="nextQ" disabled>${idx===pool.length-1?'Finish assessment':'Next question'} →</button></div>`;
 el.querySelectorAll('[data-answer]').forEach(btn=>btn.onclick=()=>{if(answered)return;answered=true;const correct=Number(btn.dataset.answer)===q.correct;if(correct)score++;btn.classList.add(correct?'correct':'incorrect');el.querySelectorAll('[data-answer]')[q.correct].classList.add('correct');el.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);$('#explanation').textContent=(correct?'Correct. ':'Not quite. ')+q.why;$('#nextQ').disabled=false});$('#nextQ').onclick=()=>{idx++;render()};
 }
 setup();
}
function readHistory(){try{const v=JSON.parse(localStorage.getItem('cv_history')||'[]');return Array.isArray(v)?v:[]}catch{return []}}
function badgeData(){const x=getStats(),h=readHistory();return [['First Steps',h.length>=1],['Quiz Explorer',h.length>=5],['Dedicated Learner',h.length>=10],['High Achiever',h.some(v=>v.pct>=90)],['Perfect Score',h.some(v=>v.pct===100)],['Phishing Investigator',(x.investigations||0)>=3],['URL Analyst',(x.checks||0)>=5],['Network Defender',(x.simulations||0)>=3],['Crypto Explorer',(x.encryptions||0)>=1],['Security All-Rounder',new Set(h.map(v=>v.topic)).size>=4]]}
function downloadCertificate(){const h=readHistory();if(!h.some(v=>v.pct>=80&&v.total>=10)){alert('Complete an assessment of at least 10 questions with 80% or higher to unlock a certificate.');return}const name=(prompt('Name for your certificate:','CyberVerse Learner')||'CyberVerse Learner').trim().slice(0,60);const safe=escapeHtml(name);const html=`<!doctype html><html><head><meta charset="utf-8"><title>CyberVerse Certificate</title><style>body{font-family:Arial;background:#091326;color:#def8ff;text-align:center;padding:7%}main{border:7px double #41ddef;padding:60px 20px}h1{color:#41ddef;font-size:40px}h2{font-size:32px}p{font-size:19px}small{color:#a9c2d8}@media print{body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><main><h1>CYBERVERSE</h1><h2>Certificate of Learning Achievement</h2><p>Presented to</p><h2>${safe}</h2><p>For completing a cybersecurity assessment with at least 80% accuracy.</p><p>${new Date().toLocaleDateString()}</p><small>Educational project achievement — not an accredited qualification</small></main><p>Open this file in a browser and use Print → Save as PDF.</p></body></html>`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([html],{type:'text/html'}));a.download='CyberVerse-Certificate.html';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function dashboard(el){const x=getStats(),history=readHistory(),badges=badgeData();const topics=[...new Set(questions.map(q=>q.topic))];el.innerHTML=`<div class="stats-grid">${[['🔎','URLs analyzed',x.checks],['🎯','Quizzes completed',x.quizzes],['🌐','Incidents contained',x.simulations],['🔐','Files encrypted',x.encryptions]].map(([icon,name,n])=>`<div class="stat-card"><span>${icon}</span><strong>${n||0}</strong><small>${name}</small></div>`).join('')}</div><div class="panel"><h3>Topic-wise performance</h3>${topics.map(t=>{const h=history.filter(v=>v.topic===t);const best=h.length?Math.max(...h.map(v=>v.pct)):0;return `<div class="topic-row"><span>${escapeHtml(t)}</span><div class="topic-track"><div style="width:${best}%"></div></div><strong>${best}%</strong></div>`}).join('')}<p class="hint">Best scores per topic. Complete a topic assessment to build your learning record.</p></div><div class="panel"><h3>Achievement badges (${badges.filter(x=>x[1]).length}/${badges.length})</h3><div class="badge-grid">${badges.map(([name,earned])=>`<div class="achievement ${earned?'earned':''}">${earned?'🏅':'🔒'} ${escapeHtml(name)}</div>`).join('')}</div><button class="primary" id="certBtn">Download completion certificate</button><p class="hint">Unlock by completing a 10+ question assessment at 80% or above. Download the certificate HTML, then print it as PDF. This is not an accredited credential.</p></div><div class="panel"><h3>Recent assessments</h3>${history.length?`<div class="history-list">${history.slice(0,12).map(h=>`<div><span>${escapeHtml(h.topic)} · ${escapeHtml(h.difficulty)}</span><strong>${h.pct}%</strong><small>${new Date(h.date).toLocaleDateString()}</small></div>`).join('')}</div>`:'<p class="hint">No completed quizzes yet.</p>'}<button id="clearStats" class="secondary">Reset all local progress</button></div>`;$('#certBtn').onclick=downloadCertificate;$('#clearStats').onclick=()=>{if(confirm('Reset all CyberVerse progress stored in this browser?')){['cv_stats','cv_best_quiz','cv_history'].forEach(k=>localStorage.removeItem(k));dashboard(el)}}}
const crypto=globalThis.crypto;

// Advanced exercises are isolated, synthetic, and never make network requests.
const scenarios=[
 {title:'Unusual login burst',logs:['09:12:04 AUTH_FAIL user=admin src=198.51.100.12','09:12:05 AUTH_FAIL user=admin src=198.51.100.12','09:12:07 AUTH_FAIL user=admin src=198.51.100.12','09:12:10 AUTH_SUCCESS user=admin src=198.51.100.12'],answer:'Escalate and investigate',why:'Repeated failures followed by success warrant investigation, account review and MFA verification.'},
 {title:'Routine backup',logs:['02:00:00 BACKUP_START host=fileserver','02:01:42 BACKUP_COMPLETE status=success','02:01:43 INTEGRITY_CHECK result=pass'],answer:'Document as expected',why:'The scheduled backup and successful integrity check are consistent with normal activity.'},
 {title:'Outbound traffic anomaly',logs:['15:04:12 DNS_QUERY host=workstation-7 domain=unusual.example','15:04:14 NET_FLOW host=workstation-7 bytes_out=84000000','15:04:15 EDR_ALERT host=workstation-7 severity=high'],answer:'Isolate workstation',why:'An EDR alert and unusually large outbound transfer justify containment and investigation.'}
];
const phishingCases=[
 {subject:'Payroll verification required',from:'payroll@company-pay.example',body:'Your payroll will be paused. Open the link and verify your password immediately.',clues:['Lookalike sender domain','Urgency and threatened consequences','Request for credentials'],verdict:'Suspicious'},
 {subject:'Team meeting notes',from:'colleague@company.example',body:'The agenda is in our usual internal shared drive. Please review before Thursday.',clues:['No immediate credential request','No threatening language','Verify sender through an established channel if unexpected'],verdict:'Needs context'},
 {subject:'Delivery fee required',from:'shipping@parcel-update.example',body:'Your parcel is held. Pay a small fee using the attached payment link today.',clues:['Unexpected payment request','Unverified sender domain','Urgent external payment link'],verdict:'Suspicious'},
 {subject:'Unexpected MFA code',from:'security@company.example',body:'Your one-time sign-in code is 000000. Do not share it.',clues:['Unexpected code may indicate attempted login','Never share MFA codes','Verify through the official account portal'],verdict:'Needs context'}
];
function advancedAddon(el,kind){
 const wrap=document.createElement('section');wrap.className='advanced-addons';el.append(wrap);
 if(kind==='password'){
  wrap.innerHTML=`<div class="panel"><h3>Advanced password challenge</h3><p class="hint">Choose the safer password practice. Do not enter real credentials.</p><select id="pwChallenge"><option value="">Select an answer</option><option value="reuse">Reuse one long password everywhere</option><option value="unique">Use unique passphrases with a password manager and MFA</option><option value="rotate">Change every password daily</option></select><button class="primary" id="pwChallengeCheck">Check answer</button><p id="pwChallengeResult" class="feedback" aria-live="polite"></p></div>`;
  wrap.querySelector('#pwChallengeCheck').onclick=()=>{const correct=wrap.querySelector('#pwChallenge').value==='unique';wrap.querySelector('#pwChallengeResult').textContent=correct?'Correct. Unique passwords limit damage from reused credentials; MFA adds protection.':'Try again. Password reuse increases credential-stuffing risk.';if(correct)inc('challenges')};
 }
 if(kind==='phishing'){
  let i=0;wrap.innerHTML=`<div class="panel"><h3>Phishing email investigation</h3><p class="hint">Fictional messages only. Judge the evidence rather than trusting a sender name.</p><div id="caseDisplay"></div><div class="input-row"><button class="secondary" id="phishReveal">Reveal indicators</button><button class="primary" id="phishNext">Next email</button></div><p id="caseClues" class="feedback" aria-live="polite"></p></div>`;
  const render=()=>{const c=phishingCases[i];wrap.querySelector('#caseDisplay').innerHTML=`<h3>${escapeHtml(c.subject)}</h3><p><strong>From:</strong> ${escapeHtml(c.from)}</p><p>${escapeHtml(c.body)}</p>`;wrap.querySelector('#caseClues').textContent='';};render();
  wrap.querySelector('#phishReveal').onclick=()=>{const c=phishingCases[i];wrap.querySelector('#caseClues').textContent=`${c.verdict}: ${c.clues.join(' • ')}`;inc('investigations')};wrap.querySelector('#phishNext').onclick=()=>{i=(i+1)%phishingCases.length;render()};
 }
 if(kind==='network'){
  let i=0;wrap.innerHTML=`<div class="panel"><h3>Incident response scenarios</h3><p class="hint">Synthetic logs; no real traffic or system changes.</p><select id="incidentSelect">${scenarios.map((x,j)=>`<option value="${j}">${escapeHtml(x.title)}</option>`).join('')}</select><pre id="incidentLogs" class="log-view"></pre><div class="input-row"><button class="secondary" data-decision="Escalate and investigate">Investigate</button><button class="secondary" data-decision="Isolate workstation">Isolate device</button><button class="secondary" data-decision="Document as expected">Mark expected</button></div><p id="incidentFeedback" class="feedback" aria-live="polite"></p></div>`;
  const render=()=>{wrap.querySelector('#incidentLogs').textContent=scenarios[i].logs.join('\n');wrap.querySelector('#incidentFeedback').textContent=''};render();wrap.querySelector('#incidentSelect').onchange=e=>{i=Number(e.target.value);render()};wrap.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>{const c=scenarios[i],ok=b.dataset.decision===c.answer;wrap.querySelector('#incidentFeedback').textContent=(ok?'Correct. ':'Not the best response. ')+c.why;if(ok)inc('incidentsSolved')});
 }
 if(kind==='crypto'){
  wrap.innerHTML=`<div class="panel"><h3>SHA-256 file integrity checker</h3><p class="hint">Hashes are one-way fingerprints, not encryption. Everything is calculated locally.</p><input id="hashFile" type="file"/><button class="primary" id="hashButton">Calculate SHA-256</button><p id="hashOutput" class="feedback hash-output" aria-live="polite"></p><h3>Cryptography knowledge check</h3><p>Which operation can be reversed with the correct key?</p><div class="input-row"><button class="secondary" data-crypto-answer="wrong">SHA-256 hashing</button><button class="secondary" data-crypto-answer="correct">AES-GCM encryption</button></div><p id="cryptoFeedback" class="feedback"></p></div>`;
  wrap.querySelector('#hashButton').onclick=async()=>{const f=wrap.querySelector('#hashFile').files[0];if(!f){wrap.querySelector('#hashOutput').textContent='Choose a file first.';return}const bytes=await f.arrayBuffer();const digest=await crypto.subtle.digest('SHA-256',bytes);wrap.querySelector('#hashOutput').textContent=Array.from(new Uint8Array(digest),x=>x.toString(16).padStart(2,'0')).join('');inc('hashes')};wrap.querySelectorAll('[data-crypto-answer]').forEach(b=>b.onclick=()=>{const ok=b.dataset.cryptoAnswer==='correct';wrap.querySelector('#cryptoFeedback').textContent=ok?'Correct: authenticated encryption can be decrypted with the correct key.':'Hashing is one-way; choose the reversible operation.';if(ok)inc('challenges')});
 }
}
