const pointer={x:0,y:0};window.addEventListener('pointermove',e=>{pointer.x=(e.clientX/innerWidth-.5)*2;pointer.y=(e.clientY/innerHeight-.5)*2});function resize(){const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;renderer.setSize(rect.width,rect.height,false);camera.aspect=rect.width/rect.height;camera.updateProjectionMatrix()}window.addEventListener('resize',resize);resize();const clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);const t=clock.getElapsedTime();rig.position.y=Math.sin(t*.9)*.12;rig.rotation.y+=(pointer.x*.17-rig.rotation.y)*.04;rig.rotation.x+=(-pointer.y*.09-rig.rotation.x)*.04;floatIcons.forEach(({g,i})=>{g.rotation.x=t*.3+i;g.rotation.y=t*.48;g.position.y=iconPositions[i][1]+Math.sin(t*1.2+i)*.14});orbs.forEach(({m,a},i)=>{m.position.y=Math.sin(a)*1.9+Math.sin(t*1.1+i)*.1;m.rotation.y=t*.4});renderer.render(scene,camera)}animate();gsap.from('.hero-copy > *',{opacity:0,y:25,stagger:.12,duration:.75,ease:'power2.out'});gsap.from('.scene-wrap',{opacity:0,scale:.88,duration:1.1,delay:.2,ease:'power2.out'});gsap.to('.float-label',{y:-12,repeat:-1,yoyo:true,duration:2.4,stagger:.35,ease:'sine.inOut'});
